def jump(nums):
    n = len(nums)
    if n <= 1:
        return 0
    steps = 0
    cur_end = 0
    farthest = 0
    for i in range(n - 1):
        if i + nums[i] > farthest:
            farthest = i + nums[i]
        if i == cur_end:
            steps += 1
            cur_end = farthest
            if cur_end >= n - 1:
                break
    return steps

