def numSquares(n):
    squares = [i * i for i in range(1, int(n ** 0.5) + 1)]
    dp = [0] + [float('inf')] * n
    for i in range(1, n + 1):
        for sq in squares:
            if sq > i:
                break
            if dp[i - sq] + 1 < dp[i]:
                dp[i] = dp[i - sq] + 1
    return dp[n]

