def wordBreak(s, wordDict):
    words = set(wordDict)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for w in words:
            lw = len(w)
            if lw <= i and dp[i - lw] and s[i - lw:i] == w:
                dp[i] = True
                break
    return dp[n]

