def longestCommonSubsequence(text1, text2):
    dp = [0] * (len(text2) + 1)
    for a in text1:
        prev = 0
        for j, b in enumerate(text2, 1):
            tmp = dp[j]
            if a == b:
                dp[j] = prev + 1
            elif dp[j - 1] > dp[j]:
                dp[j] = dp[j - 1]
            prev = tmp
    return dp[len(text2)]

