def minDistance(word1, word2):
    dp = list(range(len(word2) + 1))
    for i, a in enumerate(word1, 1):
        prev = dp[0]
        dp[0] = i
        for j, b in enumerate(word2, 1):
            tmp = dp[j]
            if a == b:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j], dp[j - 1])
            prev = tmp
    return dp[len(word2)]

